#include <omp.h>
#include <cmath>
#include <cstring>
#include <vector>
#include <algorithm>
static std::vector<mjData*> datas;
static const mjModel* oldm=nullptr;
static inline double sq(double v){return v*v;}
static inline void foot(const double* q,int leg,double* out){
 const double* j=q+7+leg*5;double ya=j[0],ro=j[1],hp=j[2],kn=j[3],an=j[4];
 double x=-.4*sin(hp)-.4*sin(hp+kn)-.05*sin(hp+kn+an);
 double z=-.4*cos(hp)-.4*cos(hp+kn)-.05*cos(hp+kn+an);
 double y0=(leg==0?1:-1)*.11536,y=y0*cos(ro)-z*sin(ro);z=y0*sin(ro)+z*cos(ro);x+=.039468;
 double xx=x*cos(ya)-y*sin(ya);y=x*sin(ya)+y*cos(ya)+(leg==0?1:-1)*.0875;x=xx;z-=.1742;
 double tx=2*(q[5]*z-q[6]*y),ty=2*(q[6]*x-q[4]*z),tz=2*(q[4]*y-q[5]*x);
 out[0]=q[0]+x+q[3]*tx+q[5]*tz-q[6]*ty;
 out[1]=q[1]+y+q[3]*ty+q[6]*tx-q[4]*tz;
 out[2]=q[2]+z+q[3]*tz+q[4]*ty-q[5]*tx;
}
extern "C" void evaluate(const mjModel* m,const mjData* initial,const double* controls,int pop,int H,const double* qr,const double* vr,const double* fp,double* costs,int threads){
 if(oldm!=m||datas.size()!=(size_t)threads){for(auto d:datas)mj_deleteData(d);datas.clear();for(int i=0;i<threads;i++)datas.push_back(mj_makeData(m));oldm=m;}
 #pragma omp parallel num_threads(threads)
 {
  mjData* d=datas[omp_get_thread_num()];mj_copyData(d,m,initial);
  #pragma omp for schedule(static)
  for(int p=0;p<pop;p++){
   memcpy(d->qpos,initial->qpos,m->nq*sizeof(double));memcpy(d->qvel,initial->qvel,m->nv*sizeof(double));memcpy(d->qacc_warmstart,initial->qacc_warmstart,m->nv*sizeof(double));d->time=initial->time;
   double total=0;
   for(int t=0;t<H;t++){
    const double* ctrl=controls+(p*H+t)*19;memcpy(d->ctrl,ctrl,19*sizeof(double));for(int j=0;j<10;j++)mj_step(m,d);
    const double* q=d->qpos;const double* v=d->qvel;const double* r=qr+t*26;const double* rv=vr+t*25;
    double cost=25*sq(q[0]-r[0])+50*sq(q[1]-r[1])+35*sq(q[2]-r[2]);
    cost+=60*(sq(q[4])+sq(q[5]))+15*sq(q[6]);
    cost+=1.5*sq(v[0]-rv[0])+1.5*sq(v[1]-rv[1])+.5*sq(v[2]-rv[2]);
    cost+=.1*(sq(v[3])+sq(v[4])+sq(v[5]));
    double footz=0;
    for(int l=0;l<2;l++){double f[3];foot(q,l,f);const double* fr=fp+t*6+l*3;cost+=40*sq(f[0]-fr[0])+45*sq(f[1]-fr[1])+90*sq(f[2]-fr[2]);footz+=f[2]*.5;}
    for(int j=0;j<19;j++){
     cost+=.15*sq(q[j+7]-r[j+7])+.001*sq(v[j+6]);
     double tau=(ctrl[j]-q[j+7])*m->actuator_gainprm[j*mjNGAIN]+v[j+6]*m->actuator_biasprm[j*mjNBIAS+2];cost+=.000005*sq(tau);
    }
    double height=q[2]+.7*(1-2*(sq(q[4])+sq(q[5])))-footz;cost+=100*sq(std::max(1.25-height,0.));
    if(t==H-1)cost*=5;
    total+=cost;
    if(!std::isfinite(total)){total=1e10;break;}
   }
   costs[p]=total;
  }
 }
}
