from pathlib import Path
import json
import numpy as np
from rcb_hb import Session
P=Path(__file__).resolve().parent

def main():
    s=Session('stair',instance='/app/instance.npz')
    actions=np.load(P/'actions.npy',allow_pickle=False)
    meta={}
    best={}
    if (P/'best.json').exists():
        best=json.loads((P/'best.json').read_text())
        meta={'proxy':best['proxy'],'source':best['source']}
    s.save_trajectory(actions,P/'trajectory.npz',meta=meta)
    first=s.replay(actions)
    second=s.replay(actions)
    assert first['state_sha']==second['state_sha']
    assert first['sim_steps']==len(actions)
    if 'state_sha' in best:
        assert first['state_sha']==best['state_sha']
    print({'steps':first['sim_steps'],'state_sha':first['state_sha'],'deterministic':True})

if __name__=='__main__':
    main()
